class Solution {
    public int mostFrequent(int[] nums, int key) {
        int[] count = new int[1001];
        int bestValue = 0;
        int bestCount = 0;
        for (int i = 0; i + 1 < nums.length; i++) {
            if (nums[i] == key) {
                int follower = nums[i + 1];
                count[follower]++;
                if (count[follower] > bestCount) {
                    bestCount = count[follower];
                    bestValue = follower;
                }
            }
        }
        return bestValue;
    }
}

import java.util.HashMap;
import java.util.Map;

class Solution {
    public int mostFrequent(int[] nums, int key) {
        Map<Integer, Integer> counts = new HashMap<>();
        int bestValue = 0;
        int bestCount = 0;
        for (int i = 0; i + 1 < nums.length; i++) {
            if (nums[i] == key) {
                int follower = nums[i + 1];
                int newCount = counts.getOrDefault(follower, 0) + 1;
                counts.put(follower, newCount);
                if (newCount > bestCount) {
                    bestCount = newCount;
                    bestValue = follower;
                }
            }
        }
        return bestValue;
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

class Solution {
    public int mostFrequent(int[] nums, int key) {
        List<Integer> followers = new ArrayList<>();
        for (int i = 0; i + 1 < nums.length; i++) {
            if (nums[i] == key) {
                followers.add(nums[i + 1]);
            }
        }

        Collections.sort(followers);
        int bestValue = followers.get(0);
        int bestCount = 0;
        int index = 0;
        while (index < followers.size()) {
            int value = followers.get(index);
            int start = index;
            while (index < followers.size() && followers.get(index) == value) {
                index++;
            }
            int runLength = index - start;
            if (runLength > bestCount) {
                bestCount = runLength;
                bestValue = value;
            }
        }
        return bestValue;
    }
}

import java.util.HashSet;
import java.util.Set;

class Solution {
    public int mostFrequent(int[] nums, int key) {
        Set<Integer> candidates = new HashSet<>();
        for (int i = 0; i + 1 < nums.length; i++) {
            if (nums[i] == key) {
                candidates.add(nums[i + 1]);
            }
        }

        int bestValue = 0;
        int bestCount = 0;
        for (int candidate : candidates) {
            int currentCount = 0;
            for (int i = 0; i + 1 < nums.length; i++) {
                if (nums[i] == key && nums[i + 1] == candidate) {
                    currentCount++;
                }
            }
            if (currentCount > bestCount) {
                bestCount = currentCount;
                bestValue = candidate;
            }
        }
        return bestValue;
    }
}
